import Foundation
func serviceCalls() {
    ARAnalytics.setup(withAnalytics: [ARHockeyAppBetaID: "unavailable", ARHockeyAppLiveID: "unavailable", ARSegmentioWriteKey: "unavailable"])
    ARAnalytics.event("Session Started")
    ARAnalytics.event("Placed a bid", withProperties: ["top_bidder": false])
    Stripe.setDefaultPublishableKey("unavailable")
    let client: STPAPIClient = STPAPIClient.shared()
    let card = STPCardParams()
    card.number = "unavailable"
    card.expMonth = 0
    card.expYear = 0
    card.cvc = "unavailable"
    card.address.postalCode = "unavailable"
    let completion: ((STPToken?, Error?) -> Void)? = nil
    client.createToken(withCard: card, completion: completion)
}
func readToken(_ token: STPToken) -> (String, String?, String?, String?) {
    return (token.tokenId, token.card?.name, token.card?.last4, token.card.map { String($0.brand.rawValue) })
}
